    /// <param name="projectorGeometry">Size/Position data for a windowed projector, in Qt Base64 encoded format. Mutually exclusive with `monitorIndex`</param>
    /// <param name="cancellationToken">A token to cancel the asynchronous operation.</param>
    /// <returns>A task that completes when OBS has processed the request.</returns>
    public Task OpenSourceProjectorAsync(
        int? monitorIndex = null,
        string? projectorGeometry = null,
        CancellationToken cancellationToken = default
    ) =>
        client.Ui.OpenSourceProjectorAsync(
            new ObsWebSocket.Core.Protocol.Requests.OpenSourceProjectorRequestData(
                sourceName: handle.Name,
                sourceUuid: handle.Uuid,
                canvasUuid: handle.Canvas.Uuid,
                monitorIndex: monitorIndex,
                projectorGeometry: projectorGeometry
            ),
            cancellationToken
        );

    /// <summary>
    /// Saves a screenshot of a source to the filesystem.
    /// 
    /// The `imageWidth` and `imageHeight` parameters are treated as &quot;scale to inner&quot;, meaning the smallest ratio will be used and the aspect ratio of the original resolution is kept.
    /// If `imageWidth` and `imageHeight` are not specified, the compressed image will use the full resolution of the source.
    /// 
    /// **Compatible with inputs and scenes.**
    /// </summary>
    /// <param name="imageFormat">Image compression format to use. Use `GetVersion` to get compatible image formats</param>
    /// <param name="imageFilePath">Path to save the screenshot file to. Eg. `C:\Users\user\Desktop\screenshot.png`</param>
    /// <param name="imageWidth">Width to scale the screenshot to</param>
    /// <param name="imageHeight">Height to scale the screenshot to</param>
    /// <param name="imageCompressionQuality">Compression quality to use. 0 for high compression, 100 for uncompressed. -1 to use &quot;default&quot; (whatever that means, idk)</param>
    /// <param name="cancellationToken">A token to cancel the asynchronous operation.</param>
    /// <returns>A task that completes when OBS has processed the request.</returns>
    public Task SaveSourceScreenshotAsync(
        string imageFormat,
        string imageFilePath,
        int? imageWidth = null,
        int? imageHeight = null,
        int? imageCompressionQuality = null,
        CancellationToken cancellationToken = default
    ) =>
        client.Sources.SaveSourceScreenshotAsync(
            new ObsWebSocket.Core.Protocol.Requests.SaveSourceScreenshotRequestData(
                sourceName: handle.Name,
                sourceUuid: handle.Uuid,
                canvasUuid: handle.Canvas.Uuid,
                imageFormat: imageFormat,
                imageFilePath: imageFilePath,
                imageWidth: imageWidth,
                imageHeight: imageHeight,
                imageCompressionQuality: imageCompressionQuality
            ),
            cancellationToken
        );

}

/// <summary>
/// Addresses one thing in OBS, so the requests about it need not restate which.
/// </summary>
public static class ObsWebSocketHandleExtensions
{
    extension(ObsWebSocketClient client)
    {
        /// <summary>Every request about one filter.</summary>
        /// <param name="handle">The filter, which a name or a uuid converts to.</param>
        public FilterOperations Filter(FilterHandle handle) => new(client, handle);
    }

    extension(ObsWebSocketClient client)
    {
        /// <summary>Every request about one input.</summary>
        /// <param name="handle">The input, which a name or a uuid converts to.</param>
        public InputOperations Input(InputHandle handle) => new(client, handle);
    }

    extension(ObsWebSocketClient client)
    {
        /// <summary>Every request about one scene.</summary>
        /// <param name="handle">The scene, which a name or a uuid converts to.</param>
        public SceneOperations Scene(SceneHandle handle) => new(client, handle);
    }

    extension(ObsWebSocketClient client)
    {
        /// <summary>Every request about one scene item.</summary>
        /// <param name="handle">The scene item, which a name or a uuid converts to.</param>
        public SceneItemOperations SceneItem(SceneItemHandle handle) => new(client, handle);
    }

    extension(ObsWebSocketClient client)
    {
        /// <summary>Every request about one source.</summary>
        /// <param name="handle">The source, which a name or a uuid converts to.</param>
        public SourceOperations Source(SourceHandle handle) => new(client, handle);
    }

}

